import React, { useRef, useEffect } from 'react';
import ErrorBoundary from './ErrorBoundary';
import { motion } from 'framer-motion';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import SwipeHint from './SwipeHint';
import { useAuth } from '../contexts/AuthContext';
import SyncStatus from './SyncStatus';
import AppNavigation from './AppNavigation';
import AppFooter from './AppFooter';
import FloatingActionButton from './FloatingActionButton';
import PayOnboarding from './PayOnboarding';
import { useData } from '../contexts/DataContext';
import { calculateDayEarnings } from '../features/payperiod/payStructure';
import { trackEvent, trackPageView, setAnalyticsUserProperties } from '../services/productAnalytics';
import AnalyticsConsent from './AnalyticsConsent';

// Bottom-nav tab order, swiping left/right steps through these.
const TAB_ORDER = [
  '/app/dashboard',
  '/app/entries',
  '/app/invoice',
  '/app/profile',
];

const Layout = () => {
  const { user } = useAuth();
  const { logs, updateLogs, paymentConfig, needsOnboarding, completeOnboarding } = useData();
  const navigate = useNavigate();
  const location = useLocation();
  const touchStart = useRef(null);
  const previousPath = useRef(location.pathname);
  const previousTabIndex = TAB_ORDER.findIndex((p) => previousPath.current.startsWith(p));
  const currentTabIndex = TAB_ORDER.findIndex((p) => location.pathname.startsWith(p));
  const pageDirection = previousTabIndex >= 0 && currentTabIndex >= 0 && currentTabIndex < previousTabIndex ? -1 : 1;

  useEffect(() => {
    trackPageView(location.pathname);
    previousPath.current = location.pathname;
  }, [location.pathname]);

  useEffect(() => {
    if (!user) return;
    setAnalyticsUserProperties({
      account_type: user.isGuest ? 'guest' : (user.role || 'free'),
      pay_model: paymentConfig?.model || 'unknown',
    });
  }, [user, paymentConfig?.model]);

  const onTouchStart = (e) => {
    // Don't hijack pans on the map or any horizontal scroller.
    if (e.target.closest && e.target.closest('.leaflet-container, [data-no-swipe]')) {
      touchStart.current = null;
      return;
    }
    const t = e.touches[0];
    touchStart.current = { x: t.clientX, y: t.clientY };
  };

  const onTouchEnd = (e) => {
    if (!touchStart.current) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.current.x;
    const dy = t.clientY - touchStart.current.y;
    touchStart.current = null;
    // Require a clear, mostly-horizontal swipe.
    if (Math.abs(dx) < 70 || Math.abs(dy) > 55) return;
    let curr = TAB_ORDER.findIndex((p) => location.pathname.startsWith(p));
    if (curr < 0) curr = 0; // /app index → treat as dashboard
    const next = dx < 0 ? curr + 1 : curr - 1;
    if (next >= 0 && next < TAB_ORDER.length) {
      if (navigator.vibrate) navigator.vibrate(8);
      navigate(TAB_ORDER[next]);
    }
  };

  // Handle quick entry from floating action button
  const handleQuickEntry = async (entryData) => {
    try {
      // Model-aware total: uses stops/miles/hours per the active pay structure,
      // plus any extra. Matches the daily form and the FAB.
      const total =
        calculateDayEarnings(paymentConfig, {
          quantity: parseFloat(entryData.stops) || 0,
          miles: parseFloat(entryData.miles) || 0,
        }) + (parseFloat(entryData.extra) || 0);

      const newEntry = {
        id: Date.now(),
        ...entryData,
        total,
        timestamp: new Date().toISOString(),
      };
      
      const updatedLogs = [...(logs || []), newEntry].sort(
        (a, b) => new Date(b.date) - new Date(a.date)
      );
      
      await updateLogs(updatedLogs);
      trackEvent('daily_entry_created', {
        entry_method: 'quick',
        pay_model: paymentConfig?.model || 'unknown',
        offline: !navigator.onLine,
        is_first_entry: (logs || []).length === 0,
      });
      
      // Add haptic feedback for success
      if (navigator.vibrate) {
        navigator.vibrate([10, 50, 10]);
      }
      
    } catch (error) {
      console.error('Error adding quick entry:', error);
      // Add haptic feedback for error
      if (navigator.vibrate) {
        navigator.vibrate([100, 50, 100]);
      }
      throw error;
    }
  };

  // First-run gate: brand-new users set up their pay before entering the app.
  if (needsOnboarding) {
    return (
      <>
        <PayOnboarding onComplete={completeOnboarding} />
        <AnalyticsConsent />
      </>
    );
  }

  return (
    <div className="min-h-[100dvh] bg-gradient-to-br from-background via-background to-primary/5 flex flex-col pt-safe">
      <SyncStatus />

      <main
        className="w-full flex-grow overflow-y-auto touch-manipulation"
        onTouchStart={onTouchStart}
        onTouchEnd={onTouchEnd}
      >
        {/* Full-width scroll area; an inner block owns the max-width + centering
            so it stays centred on iOS WebKit (a flex item with max-width can
            left-bias under align-items:stretch). */}
        <div className="w-full max-w-6xl mx-auto pt-8 pb-8 px-4">
          <ErrorBoundary>
            <motion.div
              key={location.pathname}
              initial={{ opacity: 0, x: pageDirection * 14, y: 3 }}
              animate={{ opacity: 1, x: 0, y: 0 }}
              transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }}
            >
              <Outlet />
            </motion.div>
          </ErrorBoundary>
          <AppFooter />
        </div>
      </main>

      <AnalyticsConsent />
      <SwipeHint />
      <AppNavigation className="flex-shrink-0 pb-safe" />

      {/* Floating Action Button for Quick Entry */}
      {user && (
        <FloatingActionButton
          onAddEntry={handleQuickEntry}
          isVisible={true}
        />
      )}
    </div>
  );
};

export default Layout;
