import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle } from "./ui/card";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Alert, AlertDescription } from "./ui/alert";
import { Separator } from "./ui/separator";
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signInAnonymously,
  RecaptchaVerifier,
  signInWithPhoneNumber,
} from "firebase/auth";
import { auth, signInWithGoogle } from "../services/firebase";
import { Loader2, Mail, Phone, AlertCircle } from "lucide-react";
import Logo from "./Logo";
import { trackEvent } from "../services/productAnalytics";

const PHONE_SIGN_IN_ENABLED = false;

const Auth = ({ onBack }) => {
  const [method, setMethod] = useState("email"); // 'email', 'phone', 'google', 'anonymous'
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [verificationId, setVerificationId] = useState("");
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    phone: "",
    code: "",
  });

  const setupRecaptcha = () => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(auth, "recaptcha-container", {
        size: "invisible",
        callback: () => {},
      });
    }
  };

  const handleAuth = async (type) => {
    setError("");
    setLoading(true);

    try {
      if (type === "email") {
        isLogin
          ? await signInWithEmailAndPassword(auth, formData.email, formData.password)
          : await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        trackEvent(isLogin ? "login_completed" : "signup_completed", { method: "email" });
      } else if (type === "google") {
        await signInWithGoogle();
        trackEvent("login_completed", { method: "google" });
      } else if (type === "phone") {
        if (!verificationId) {
          setupRecaptcha();
          const confirmation = await signInWithPhoneNumber(auth, formData.phone, window.recaptchaVerifier);
          setVerificationId(confirmation.verificationId);
        } else {
          // Verify the code here
        }
      } else if (type === "anonymous") {
        await signInAnonymously(auth);
        trackEvent("guest_started", { method: "anonymous" });
      }
    } catch (err) {
      setError(getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  const getErrorMessage = (error) => {
    switch (error.code) {
      case "auth/email-already-in-use":
        return "This email is already registered";
      case "auth/invalid-email":
        return "Invalid email address";
      case "auth/weak-password":
        return "Password should be at least 6 characters";
      case "auth/user-not-found":
      case "auth/wrong-password":
        return "Invalid email or password";
      default:
        return error.message;
    }
  };

  return (
    <div className="min-h-screen animated-gradient flex items-center justify-center p-4">
      {/* Background decoration */}
      <div className="absolute inset-0 overflow-hidden">
        <div className="ambient-blob -top-4 -right-4 w-96 h-96 bg-primary/15"></div>
        <div className="ambient-blob -bottom-6 -left-6 w-80 h-80 bg-secondary/10" style={{ animationDelay: "-8s" }}></div>
      </div>
      
      <motion.div
        initial={{ opacity: 0, y: 30, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        transition={{ duration: 0.8, ease: [0.23, 1, 0.32, 1] }}
        className="relative z-10 w-full max-w-md"
      >
        <Card className="overflow-hidden brand-glow border border-border bg-card/95 backdrop-blur-xl">
          <CardHeader className="relative brand-surface py-9 text-center">
            <div className="absolute -top-4 -right-4 w-24 h-24 bg-primary/10 rounded-full blur-2xl"></div>
            <div className="absolute -bottom-6 -left-6 w-32 h-32 bg-secondary/10 rounded-full blur-2xl"></div>
            
            <div className="relative z-10 mb-4 flex justify-center">
              <Logo variant="icon" className="w-16 h-16" />
            </div>
            
            <CardTitle className="relative z-10 text-3xl font-bold mb-2">
              {method === "email" ? (isLogin ? "Welcome Back" : "Create Account") : "Sign In"}
            </CardTitle>
            <p className="relative z-10 text-muted-foreground font-medium">
              {method === "email" 
                ? (isLogin ? "Sign in to your Stop Tracker account" : "Join Stop Tracker today")
                : "Choose your sign-in method"
              }
            </p>
          </CardHeader>
          <CardContent className="p-8 bg-card">
        <AnimatePresence>
          {error && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
            >
              <Alert className="bg-red-50 border-2 border-red-200 dark:bg-red-900/20 dark:border-red-800">
                <AlertCircle className="h-5 w-5 text-red-500" />
                <AlertDescription className="text-red-700 dark:text-red-400 font-medium">{error}</AlertDescription>
              </Alert>
            </motion.div>
          )}
        </AnimatePresence>

        <div className={`grid ${PHONE_SIGN_IN_ENABLED ? "grid-cols-2" : "grid-cols-1"} gap-3 mb-8`}>
          <Button
            onClick={() => setMethod("email")}
            className={`relative py-4 rounded-2xl font-semibold transition-all duration-300 transform hover:scale-105 ${
              method === "email" 
                ? "bg-primary text-primary-foreground shadow-sm" 
                : "bg-muted text-foreground hover:bg-primary/10"
            }`}
          >
            <Mail className="mr-2 w-5 h-5" />
            Email
          </Button>
          {PHONE_SIGN_IN_ENABLED && (
            <Button
              onClick={() => setMethod("phone")}
              className={`relative py-4 rounded-2xl font-semibold transition-all duration-300 transform hover:scale-105 ${
                method === "phone"
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "bg-muted text-foreground hover:bg-primary/10"
              }`}
            >
              <Phone className="mr-2 w-5 h-5" />
              Phone
            </Button>
          )}
        </div>

        {method === "email" && (
          <form
            onSubmit={(e) => {
              e.preventDefault();
              handleAuth("email");
            }}
            className="space-y-4"
          >
            <Input
              type="email"
              placeholder="Email"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              required
              className="bg-input text-foreground"
            />
            <Input
              type="password"
              placeholder="Password"
              value={formData.password}
              onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              required
              className="bg-input text-foreground"
            />
            <Button type="submit" className="w-full bg-primary text-primary-foreground hover:opacity-90" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 className="mr-2 w-4 h-4 animate-spin" />
                  {isLogin ? "Logging in..." : "Creating account..."}
                </>
              ) : isLogin ? (
                "Login"
              ) : (
                "Sign Up"
              )}
            </Button>
            <Button
              type="button"
              variant="ghost"
              className="w-full"
              onClick={() => setIsLogin(!isLogin)}
            >
              {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Login"}
            </Button>
          </form>
        )}

        {PHONE_SIGN_IN_ENABLED && method === "phone" && (
          <form
            onSubmit={(e) => {
              e.preventDefault();
              handleAuth("phone");
            }}
            className="space-y-4"
          >
            {!verificationId ? (
              <Input
                type="tel"
                placeholder="Phone number (e.g., +447123456789)"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                required
                className="bg-input text-foreground"
              />
            ) : (
              <Input
                type="text"
                placeholder="Enter verification code"
                value={formData.code}
                onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                required
                className="bg-input text-foreground"
              />
            )}
            <Button type="submit" className="w-full bg-primary text-primary-foreground hover:opacity-90" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 className="mr-2 w-4 h-4 animate-spin" />
                  {verificationId ? "Verifying..." : "Sending code..."}
                </>
              ) : verificationId ? (
                "Verify Code"
              ) : (
                "Send Code"
              )}
            </Button>
          </form>
        )}

        <div className="relative py-4">
          <Separator />
          <div className="relative flex justify-center text-sm text-muted-foreground">
            Or continue with
          </div>
        </div>

        <div className="grid gap-4">
          <Button
            onClick={() => handleAuth("google")}
            variant="outline"
            className="w-full border-primary/40 text-primary hover:bg-primary/5"
            disabled={loading}
          >
            Continue with Google
          </Button>
          <Button
            onClick={() => handleAuth("anonymous")}
            variant="outline"
            className="w-full border-primary/40 text-primary hover:bg-primary/5"
            disabled={loading}
          >
            Continue as Guest
          </Button>
        </div>

        {onBack && (
          <Button onClick={onBack} variant="ghost" className="w-full mt-4">
            Back to Home
          </Button>
        )}
            <div id="recaptcha-container" />
          </CardContent>
        </Card>
      </motion.div>
    </div>
  );
};

export default Auth;