import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent } from "./ui/card";
import { Input } from "./ui/input";
import { Button } from "./ui/button";
import {
  Save,
  Calendar,
  DollarSign,
  FileText,
  CloudOff,
  Loader,
  CheckCircle,
  Undo
} from "lucide-react";
import { useData } from "../contexts/DataContext";
import { calculateDayEarnings, PAY_MODELS } from "../features/payperiod/payStructure";
import { Money } from "./ui/money";
import { AnimatedMoney } from "./ui/animated-money";
import { trackEvent } from "../services/productAnalytics";
import { useSearchParams } from "react-router-dom";

const DEFAULT_CONFIG = {
  model: "tiered_stops",
  thresholds: [{ stopCount: 110, rate: 1.98 }, { rate: 1.48 }],
  excessParcelRate: 0.05,
};

const toLocalDateString = (date = new Date()) => {
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return local.toISOString().slice(0, 10);
};

const mergeLogByDate = (logs, log) =>
  [
    ...(logs || []).filter((item) => item.id !== log.id && item.date !== log.date),
    log,
  ].sort((a, b) => new Date(b.date) - new Date(a.date));

const StopEntryForm = ({ logs = [], updateLogs, syncStatus }) => {
  // Initialize logs as an empty array if null
  const safetyLogs = logs || [];
  
  // Smart defaults - get last used values
  const getSmartDefaults = () => {
    try {
      const lastEntry = localStorage.getItem('last-entry-data');
      if (lastEntry) {
        const parsed = JSON.parse(lastEntry);
        return {
          date: toLocalDateString(), // Always use today's date
          stops: parsed.stops || "",
          miles: parsed.miles || "",
          extra: parsed.extra || "",
          notes: parsed.notes || "",
        };
      }
    } catch (error) {
      console.error('Error loading smart defaults:', error);
    }

    return {
      date: toLocalDateString(),
      stops: "",
      miles: "",
      extra: "",
      notes: "",
    };
  };

  const [entry, setEntry] = useState(getSmartDefaults());
  const [searchParams, setSearchParams] = useSearchParams();
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { paymentConfig } = useData();
  const config = paymentConfig || DEFAULT_CONFIG;
  const model = config.model || "tiered_stops";
  const meta = PAY_MODELS.find((m) => m.id === model) || PAY_MODELS[0];
  const todayDate = toLocalDateString();
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayDate = toLocalDateString(yesterday);
  const existingForDate = useMemo(
    () => safetyLogs.find((log) => log.date === entry.date) || null,
    [safetyLogs, entry.date]
  );
  const [showAllEntries, setShowAllEntries] = useState(false);
  const [lastSavedEntry, setLastSavedEntry] = useState(null);
  const [showUndo, setShowUndo] = useState(false);
  const [lastSaveAction, setLastSaveAction] = useState("saved");
  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [pendingEntries, setPendingEntries] = useState([]);
  const [retryCount, setRetryCount] = useState(0);
  
  // Form refs for smart scrolling
  const formRef = useRef(null);
  const activeInputRef = useRef(null);
  const stopsInputRef = useRef(null);
  const extraInputRef = useRef(null);

  // Smart keyboard handling for mobile
  const handleInputFocus = useCallback((inputRef) => {
    activeInputRef.current = inputRef;
    
    // Add haptic feedback
    if (navigator.vibrate) {
      navigator.vibrate(5);
    }
    
    // Delay scroll to allow keyboard to appear
    setTimeout(() => {
      if (inputRef?.current && window.innerWidth <= 768) {
        // Calculate scroll position to keep input visible above keyboard
        const inputRect = inputRef.current.getBoundingClientRect();
        const viewportHeight = window.innerHeight;
        const estimatedKeyboardHeight = Math.min(viewportHeight * 0.35, 300);
        const availableHeight = viewportHeight - estimatedKeyboardHeight;
        const targetY = inputRect.top + window.scrollY;
        const scrollTo = Math.max(0, targetY - (availableHeight * 0.3));
        
        window.scrollTo({
          top: scrollTo,
          behavior: 'smooth'
        });
      }
    }, 150);
  }, []);

  // Handle input blur
  const handleInputBlur = useCallback(() => {
    activeInputRef.current = null;
  }, []);

  const selectDate = useCallback((date) => {
    if (!date) return;

    const existing = safetyLogs.find((log) => log.date === date);
    if (existing) {
      setEntry({
        date,
        stops: existing.stops != null ? String(existing.stops) : "",
        miles: existing.miles != null ? String(existing.miles) : "",
        extra: existing.extra != null && existing.extra !== 0 ? String(existing.extra) : "",
        notes: existing.notes || "",
      });
    } else {
      setEntry((prev) => ({
        ...prev,
        date,
        stops: "",
        miles: "",
        extra: "",
        notes: "",
      }));
    }

    setError(null);
    setSuccess(false);
    setShowUndo(false);
  }, [safetyLogs]);

  useEffect(() => {
    const requestedDate = searchParams.get("date");
    if (!requestedDate) return;

    if (requestedDate <= todayDate) {
      selectDate(requestedDate);
    }

    setSearchParams({}, { replace: true });
  }, [searchParams, selectDate, setSearchParams, todayDate]);

  // Debounced input handler to reduce unnecessary re-renders
  const debouncedHandleChange = useCallback((e) => {
    const { name, value } = e.target;
    
    // Clear error when user starts typing
    if (error) {
      setError(null);
    }
    
    setEntry(prev => ({
      ...prev,
      [name]: value
    }));
  }, [error]);

  // Keyboard height detection for better mobile experience
  useEffect(() => {
    if (typeof window === 'undefined') return;
    
    const handleResize = () => {
      if (window.innerWidth <= 768) {
        const currentHeight = window.innerHeight;
        const fullHeight = window.screen.height;
        const heightDiff = fullHeight - currentHeight;
        
        if (heightDiff > 150) {
          setKeyboardHeight(heightDiff);
        } else {
          setKeyboardHeight(0);
        }
      }
    };

    const handleVisibilityChange = () => {
      if (!document.hidden) {
        // Reset keyboard height when app becomes visible
        setTimeout(handleResize, 100);
      }
    };

    window.addEventListener('resize', handleResize);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    
    return () => {
      window.removeEventListener('resize', handleResize);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  // Reset success message after 3 seconds
  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => {
        setSuccess(false);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  // Auto-hide undo after 10 seconds
  useEffect(() => {
    if (showUndo) {
      const timer = setTimeout(() => {
        setShowUndo(false);
        setLastSavedEntry(null);
      }, 10000);
      return () => clearTimeout(timer);
    }
  }, [showUndo]);

  // Online/offline status monitoring
  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      // Try to sync pending entries when coming back online
      if (pendingEntries.length > 0) {
        syncPendingEntries();
      }
    };
    
    const handleOffline = () => {
      setIsOnline(false);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [pendingEntries]);

  // Load pending entries from localStorage on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem('pending-entries');
      if (stored) {
        setPendingEntries(JSON.parse(stored));
      }
    } catch (error) {
      console.error('Error loading pending entries:', error);
    }
  }, []);

  // Sync pending entries when online
  const syncPendingEntries = async () => {
    if (pendingEntries.length === 0 || !isOnline || !updateLogs) return;

    try {
      // Add haptic feedback for sync start
      if (navigator.vibrate) {
        navigator.vibrate([20, 30, 20]);
      }

      for (const pendingEntry of pendingEntries) {
        const updatedLogs = mergeLogByDate(safetyLogs, pendingEntry);
        await updateLogs(updatedLogs);
      }

      // Clear pending entries after successful sync
      setPendingEntries([]);
      localStorage.removeItem('pending-entries');
      
    } catch (error) {
      console.error('Error syncing pending entries:', error);
      // Keep entries pending for next retry
    }
  };

  // Removed - replaced with debouncedHandleChange below for better performance

  // Memoize expensive calculations to prevent unnecessary re-renders
  const estimatedEarnings = useMemo(() => {
    if (!entry.stops) return 0;

    const extraNum = entry.extra ? parseFloat(entry.extra) || 0 : 0;

    return calculateDayEarnings(config, {
      quantity: parseFloat(entry.stops) || 0,
      miles: parseFloat(entry.miles) || 0,
    }) + extraNum;
  }, [entry.stops, entry.miles, entry.extra, config]);

  // Memoize recent entries to avoid unnecessary re-processing
  const recentEntries = useMemo(() => {
    return showAllEntries ? safetyLogs : safetyLogs.slice(0, 2);
  }, [safetyLogs, showAllEntries]);

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSaving(true);
    setError(null);
    
    try {
      if (!entry.stops) {
        throw new Error("Please enter number of stops");
      }
      
      const stops = parseFloat(entry.stops) || 0;
      const extra = entry.extra ? parseFloat(entry.extra) : 0;
      const miles = parseFloat(entry.miles) || 0;
      const total = calculateDayEarnings(config, { quantity: stops, miles }) + extra;

      const isUpdatingExisting = Boolean(existingForDate);
      const newLog = {
        ...(existingForDate || {}),
        id: existingForDate?.id || Date.now(),
        date: entry.date,
        stops,
        extra,
        total,
        notes: entry.notes,
        timestamp: existingForDate?.timestamp || new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        ...(model === 'sliding_scale' ? { miles } : {}),
      };
      
      // Store entry for undo functionality
      setLastSavedEntry({
        entry: { ...newLog },
        previousLogs: [...safetyLogs]
      });

      // Handle offline scenario
      if (!isOnline) {
        // Save to pending entries for later sync
        const newPendingEntries = [
          ...pendingEntries.filter((item) => item.id !== newLog.id && item.date !== newLog.date),
          newLog,
        ];
        setPendingEntries(newPendingEntries);
        
        // Store in localStorage
        try {
          localStorage.setItem('pending-entries', JSON.stringify(newPendingEntries));
        } catch (error) {
          console.error('Error storing pending entry:', error);
        }
        
        // Add to local logs for immediate UI feedback
        const updatedLogs = mergeLogByDate(safetyLogs, newLog);
        
        // Update logs locally but show offline message
        if (updateLogs) {
          await updateLogs(updatedLogs);
        }
        
      } else {
        // Online - try to save with retry logic
        let saveSuccessful = false;
        let attempts = 0;
        const maxAttempts = 3;

        while (!saveSuccessful && attempts < maxAttempts) {
          try {
            const updatedLogs = mergeLogByDate(safetyLogs, newLog);
            
            if (updateLogs) {
              await updateLogs(updatedLogs);
            }
            saveSuccessful = true;
          } catch (saveError) {
            attempts++;
            console.error(`Save attempt ${attempts} failed:`, saveError);
            
            if (attempts === maxAttempts) {
              // Final attempt failed - treat as offline
              const newPendingEntries = [
                ...pendingEntries.filter((item) => item.id !== newLog.id && item.date !== newLog.date),
                newLog,
              ];
              setPendingEntries(newPendingEntries);
              localStorage.setItem('pending-entries', JSON.stringify(newPendingEntries));
              
              // Still update local logs for UI
              const updatedLogs = mergeLogByDate(safetyLogs, newLog);
              if (updateLogs) {
                await updateLogs(updatedLogs);
              }
            } else {
              // Wait before retry
              await new Promise(resolve => setTimeout(resolve, 1000 * attempts));
            }
          }
        }
      }

      // Save smart defaults for next entry (excluding date)
      try {
        const smartDefaults = {
          stops: entry.stops,
          extra: entry.extra,
          notes: entry.notes
        };
        localStorage.setItem('last-entry-data', JSON.stringify(smartDefaults));
      } catch (error) {
        console.error('Error saving smart defaults:', error);
      }
      
      // Clear form with fresh smart defaults
      setEntry({
        date: todayDate,
        stops: "",
        miles: "",
        extra: "",
        notes: "",
      });
      
      setLastSaveAction(isUpdatingExisting ? "updated" : "saved");
      setSuccess(true);
      setShowUndo(true);
      trackEvent(isUpdatingExisting ? "daily_entry_updated" : "daily_entry_created", {
        entry_method: "full_form",
        pay_model: model,
        offline: !isOnline,
        has_extra: extra > 0,
        has_notes: Boolean(entry.notes?.trim()),
        is_first_entry: !isUpdatingExisting && safetyLogs.length === 0,
      });
      
      // Add successful save haptic feedback
      if (navigator.vibrate) {
        navigator.vibrate([50, 30, 50]);
      }
    } catch (err) {
      setError(err.message || "Failed to save entry");
    } finally {
      setSaving(false);
      setIsSubmitting(false);
    }
  };

  const handleUndo = async () => {
    if (!lastSavedEntry || !updateLogs) return;
    
    try {
      // Add haptic feedback
      if (navigator.vibrate) {
        navigator.vibrate([30, 50, 30]);
      }
      
      // Restore previous logs (remove the last added entry)
      await updateLogs(lastSavedEntry.previousLogs);
      
      // Restore the form data
      setEntry({
        date: lastSavedEntry.entry.date,
        stops: lastSavedEntry.entry.stops?.toString?.() || "",
        miles: lastSavedEntry.entry.miles?.toString?.() || "",
        extra: lastSavedEntry.entry.extra?.toString?.() || "",
        notes: lastSavedEntry.entry.notes || ""
      });
      
      setShowUndo(false);
      setLastSavedEntry(null);
      setSuccess(false);
      trackEvent("daily_entry_undone", {
        entry_method: "full_form",
        pay_model: model,
      });
      
    } catch (error) {
      console.error('Error undoing entry:', error);
      setError('Failed to undo entry');
    }
  };

  // Optimize form submission handler with proper cleanup
  const optimizedHandleSubmit = useCallback(async (e) => {
    // Prevent double submission
    if (isSubmitting) return;
    
    await handleFormSubmit(e);
  }, [isSubmitting, handleFormSubmit]);

  const renderSyncStatus = () => {
    // Show offline status if we're offline
    if (!isOnline) {
      return (
        <div className="flex items-center text-amber-600 text-sm">
          <CloudOff className="w-3 h-3 mr-1" />
          <span>Offline</span>
          {pendingEntries.length > 0 && (
            <span className="ml-1 bg-amber-100 text-amber-800 px-2 py-0.5 rounded-full text-xs">
              {pendingEntries.length} pending
            </span>
          )}
        </div>
      );
    }

    // Show pending sync status
    if (pendingEntries.length > 0) {
      return (
        <div className="flex items-center text-primary text-sm">
          <Loader className="w-3 h-3 mr-1 animate-spin" />
          <span>Syncing {pendingEntries.length} entries...</span>
        </div>
      );
    }

    // Default sync status from props
    switch (syncStatus) {
      case "syncing":
        return (
          <div className="flex items-center text-amber-500 text-sm">
            <Loader className="w-3 h-3 mr-1 animate-spin" />
            <span>Syncing...</span>
          </div>
        );
      case "synced":
        return null;
      case "offline":
        return (
          <div className="flex items-center text-amber-500 text-sm">
            <CloudOff className="w-3 h-3 mr-1" />
            <span>Working offline</span>
          </div>
        );
      case "error":
        return (
          <div className="flex items-center text-red-500 text-sm">
            <CloudOff className="w-3 h-3 mr-1" />
            <span>Sync error - will retry</span>
          </div>
        );
      default:
        return null;
    }
  };

  // Moved to memoized version above for better performance

  return (
    <div 
      ref={formRef}
      className="space-y-4 -mx-6 -mt-6"
      style={{ 
        paddingBottom: keyboardHeight > 0 ? `${keyboardHeight + 20}px` : '0px',
        transition: 'padding-bottom 0.3s ease-in-out'
      }}
    >
      <div>
        <Card className="mx-0 rounded-none border-0 shadow-none">
          <CardContent className="px-4 pt-1 pb-4">
            <form onSubmit={optimizedHandleSubmit} className="space-y-5">
              {/* Main input - model-driven hero field (most important, thumb-friendly position) */}
              <div className="brand-surface p-4 rounded-[18px]">
                <label className="block text-sm font-semibold text-primary mb-2 text-center">
                  {meta.primary.label}
                </label>

                {meta.primary.type === 'toggle' ? (
                  <div className="flex gap-3 justify-center">
                    <button
                      type="button"
                      onClick={() => setEntry(prev => ({ ...prev, stops: "1" }))}
                      className={`flex-1 h-14 rounded-[18px] border-2 font-semibold touch-manipulation transition-colors active:scale-95 ${
                        (parseFloat(entry.stops) || 0) > 0
                          ? 'bg-primary text-primary-foreground border-primary'
                          : 'border-primary/30 text-primary'
                      }`}
                    >
                      Yes
                    </button>
                    <button
                      type="button"
                      onClick={() => setEntry(prev => ({ ...prev, stops: "0" }))}
                      className={`flex-1 h-14 rounded-[18px] border-2 font-semibold touch-manipulation transition-colors active:scale-95 ${
                        entry.stops !== "" && (parseFloat(entry.stops) || 0) === 0
                          ? 'bg-primary text-primary-foreground border-primary'
                          : 'border-primary/30 text-primary'
                      }`}
                    >
                      No
                    </button>
                  </div>
                ) : (
                  <Input
                    ref={stopsInputRef}
                    type="number"
                    inputMode="numeric"
                    name="stops"
                    value={entry.stops}
                    onChange={debouncedHandleChange}
                    onFocus={() => handleInputFocus(stopsInputRef)}
                    onBlur={handleInputBlur}
                    placeholder="0"
                    required
                    className="h-16 border-2 border-primary/30 rounded-[18px] focus:border-primary focus:ring-4 focus:ring-primary/20 text-2xl font-bold touch-manipulation text-center shadow-lg tabular-nums"
                  />
                )}

                {meta.secondary?.field === 'miles' && (
                  <div className="mt-3">
                    <label className="block text-xs font-medium text-muted-foreground mb-1 text-center">
                      {meta.secondary.label}
                    </label>
                    <Input
                      type="number"
                      inputMode="numeric"
                      name="miles"
                      value={entry.miles}
                      onChange={debouncedHandleChange}
                      onFocus={() => handleInputFocus({ current: null })}
                      onBlur={handleInputBlur}
                      placeholder="0"
                      className="h-12 border-2 border-primary/30 rounded-[14px] focus:border-primary focus:ring-2 focus:ring-primary/20 text-lg font-semibold touch-manipulation text-center tabular-nums"
                    />
                  </div>
                )}

                <AnimatePresence mode="wait">
                  {entry.stops && (
                    <motion.div
                      key={estimatedEarnings}
                      initial={{ opacity: 0, y: 6, scale: 0.985 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: -4 }}
                      transition={{ duration: 0.18 }}
                      className="mt-3 rounded-[14px] border border-primary/20 bg-card/75 px-4 py-3 text-center"
                    >
                      <div className="text-[11px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">
                        Expected earnings
                      </div>
                      <div className="mt-0.5 text-2xl font-extrabold tracking-[-0.03em] text-primary">
                        <AnimatedMoney amount={estimatedEarnings} />
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>

              {/* Secondary inputs in thumb-reach zone */}
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-muted-foreground mb-2">
                      📅 Date
                    </label>
                    <div className="grid grid-cols-2 gap-2 mb-2">
                      <button
                        type="button"
                        onClick={() => selectDate(todayDate)}
                        className={`h-9 rounded-[11px] border text-xs font-semibold transition-colors ${
                          entry.date === todayDate
                            ? "border-primary bg-primary/10 text-primary"
                            : "border-border bg-card text-muted-foreground"
                        }`}
                      >
                        Today
                      </button>
                      <button
                        type="button"
                        onClick={() => selectDate(yesterdayDate)}
                        className={`h-9 rounded-[11px] border text-xs font-semibold transition-colors ${
                          entry.date === yesterdayDate
                            ? "border-primary bg-primary/10 text-primary"
                            : "border-border bg-card text-muted-foreground"
                        }`}
                      >
                        Yesterday
                      </button>
                    </div>
                    <Input
                      type="date"
                      name="date"
                      value={entry.date}
                      max={todayDate}
                      onChange={(e) => selectDate(e.target.value)}
                      onFocus={() => handleInputFocus({ current: null })}
                      onBlur={handleInputBlur}
                      required
                      className="h-12 rounded-[14px] focus:border-primary focus:ring-2 focus:ring-primary/20 text-sm touch-manipulation"
                    />
                    {existingForDate && (
                      <p className="mt-2 text-[11px] text-muted-foreground">
                        Editing saved entry
                      </p>
                    )}
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-muted-foreground mb-2">
                      💰 Extra Pay
                    </label>
                    <div className="relative">
                      <div className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none z-10">
                        <span className="text-muted-foreground text-sm font-medium">£</span>
                      </div>
                      <Input
                        ref={extraInputRef}
                        type="number"
                        inputMode="decimal"
                        name="extra"
                        value={entry.extra}
                        onChange={debouncedHandleChange}
                        onFocus={() => handleInputFocus(extraInputRef)}
                        onBlur={handleInputBlur}
                        placeholder="0.00"
                        step="0.01"
                        className="pl-10 h-12 rounded-[14px] focus:border-primary focus:ring-2 focus:ring-primary/20 text-sm touch-manipulation text-center font-medium tabular-nums"
                      />
                    </div>
                  </div>
                </div>
                
                <div>
                  <label className="block text-xs font-medium text-muted-foreground mb-2">
                    📝 Notes (Optional)
                  </label>
                  <Input
                    type="text"
                    name="notes"
                    value={entry.notes}
                    onChange={debouncedHandleChange}
                    onFocus={() => handleInputFocus({ current: null })}
                    onBlur={handleInputBlur}
                    placeholder="Additional notes..."
                    className="h-12 rounded-[14px] focus:border-primary focus:ring-2 focus:ring-primary/20 text-sm touch-manipulation"
                  />
                </div>
              </div>
              
              {/* Thumb-friendly submit area */}
              <div className="pt-6">
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center text-xs">
                    {renderSyncStatus()}
                  </div>
                </div>
                
                {/* Large, thumb-friendly submit button */}
                <Button
                  type="submit"
                  disabled={isSubmitting || !entry.stops}
                  className="w-full py-4 px-6 rounded-[18px] font-semibold text-base h-14 min-h-[56px] touch-manipulation pressable brand-glow flex items-center justify-center"
                >
                  {saving ? (
                    <>
                      <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent mr-3"></div>
                      <span>Saving Entry...</span>
                    </>
                  ) : (
                    <>
                      <motion.span
                        initial={{ scale: 0.7, rotate: -8 }}
                        animate={{ scale: 1, rotate: 0 }}
                        transition={{ type: "spring", stiffness: 420, damping: 20 }}
                        className="mr-3"
                      >
                        {existingForDate ? <CheckCircle className="h-5 w-5" /> : <Save className="h-5 w-5" />}
                      </motion.span>
                      <span>
                        {existingForDate ? "Update Entry" : "Save Entry"}
                        {entry.stops ? ` (${entry.stops} ${meta.primary.unit})` : ""}
                      </span>
                    </>
                  )}
                </Button>
                
                {/* Quick tips for first-time users */}
                {!entry.stops && (
                  <div className="mt-3 text-center">
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                      👆 Enter your delivery stops to get started
                    </p>
                  </div>
                )}
              </div>

              {/* Success/Error messages */}
              <AnimatePresence>
                {success && !showUndo && (
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    className="bg-emerald-500/10 border border-emerald-500/20 text-emerald-600 dark:text-emerald-400 p-3 rounded-[14px]"
                  >
                    <div className="flex items-center">
                      <CheckCircle className="h-4 w-4 text-green-500 mr-2" />
                      <p className="text-xs font-medium">{lastSaveAction === "updated" ? "Entry updated successfully!" : "Entry saved successfully!"}</p>
                    </div>
                  </motion.div>
                )}
                
                {/* Undo functionality */}
                {showUndo && (
                  <motion.div
                    initial={{ opacity: 0, y: 10, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: -10, scale: 0.95 }}
                    className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-[14px]"
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center">
                        <CheckCircle className="h-4 w-4 text-green-500 mr-2" />
                        <div>
                          <p className="text-xs font-medium text-amber-800 dark:text-amber-200">{lastSaveAction === "updated" ? "Entry updated successfully!" : "Entry saved successfully!"}</p>
                          <p className="text-xs text-amber-600 dark:text-amber-300 mt-1">Tap undo if this was a mistake</p>
                        </div>
                      </div>
                      <Button
                        onClick={handleUndo}
                        type="button"
                        size="sm"
                        variant="outline"
                        className="ml-3 bg-white hover:bg-amber-50 border-amber-300 text-amber-700 hover:text-amber-800 h-8 px-3 text-xs touch-manipulation active:scale-95"
                      >
                        <Undo className="h-3 w-3 mr-1" />
                        Undo
                      </Button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {error && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                  className="bg-destructive/10 border border-destructive/20 text-destructive p-4 rounded-[14px]"
                >
                  <div className="flex items-start">
                    <svg className="h-4 w-4 text-red-500 mr-2 mt-0.5 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                    <div className="flex-1">
                      <p className="text-sm font-medium">{error}</p>
                      {!isOnline && (
                        <p className="text-xs text-red-600 mt-1">
                          Your entry has been saved locally and will sync when you're back online.
                        </p>
                      )}
                    </div>
                  </div>
                </motion.div>
              )}

              {/* Offline notification */}
              {!isOnline && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-[14px]"
                >
                  <div className="flex items-center">
                    <CloudOff className="h-4 w-4 text-amber-500 mr-2" />
                    <div>
                      <p className="text-sm font-medium text-amber-800">Working offline</p>
                      <p className="text-xs text-amber-700 mt-1">
                        Entries will sync automatically when connection is restored
                      </p>
                      {pendingEntries.length > 0 && (
                        <p className="text-xs text-amber-600 mt-1">
                          {pendingEntries.length} entries waiting to sync
                        </p>
                      )}
                    </div>
                  </div>
                </motion.div>
              )}
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default StopEntryForm;